begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir map_icon_events.inc
update public.events set starts_at=now()+interval '1 day',ends_at=now()+interval '1 day 2 hours',map_icon_version_id='29000000-0000-4000-8000-000000000031' where id='29000000-0000-4000-8000-000000000050';
update private.map_icon_settings set rendering_enabled=true;
set local role authenticated;
select set_config('request.jwt.claim.sub','29000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.accept_current_event_policies('29000000-0000-4000-8000-000000000050')$$,'normal policy acceptance succeeds');
select lives_ok($$select public.publish_event('29000000-0000-4000-8000-000000000050')$$,'normal publication succeeds');
set local role anon;
select is((select count(*) from public.get_public_map_events(-122.4,37.7,-122.1,37.9,now(),now()+interval '7 days',null) where event_id='29000000-0000-4000-8000-000000000050'),1::bigint,'public event exists in bounds');
select is((select map_icon_version_id::text from public.get_public_map_events(-122.4,37.7,-122.1,37.9,now(),now()+interval '7 days',null) where event_id='29000000-0000-4000-8000-000000000050'),'29000000-0000-4000-8000-000000000031','canonical RPC exposes pinned version');
select is((select count(*) from public.get_public_map_events(-122.4,37.7,-122.1,37.9,now(),now()+interval '7 days',array['music']) where event_id='29000000-0000-4000-8000-000000000050'),0::bigint,'category filtering unchanged');
select is((select count(*) from public.get_public_map_events(-123.4,37.7,-123.1,37.9,now(),now()+interval '7 days',null) where event_id='29000000-0000-4000-8000-000000000050'),0::bigint,'viewport filtering unchanged');
select is((select count(*) from public.get_public_map_events(-122.4,37.7,-122.1,37.9,now()+interval '2 days',now()+interval '7 days',null) where event_id='29000000-0000-4000-8000-000000000050'),0::bigint,'time filtering unchanged');
reset role;
update private.map_icon_versions set state='retired' where id='29000000-0000-4000-8000-000000000031';
select is((select map_icon_version_id::text from public.get_public_map_events(-122.4,37.7,-122.1,37.9,now(),now()+interval '7 days',null) where event_id='29000000-0000-4000-8000-000000000050'),'29000000-0000-4000-8000-000000000031','retired existing version remains renderable');
update private.map_icon_settings set rendering_enabled=false;
select is((select map_icon_version_id from public.get_public_map_events(-122.4,37.7,-122.1,37.9,now(),now()+interval '7 days',null) where event_id='29000000-0000-4000-8000-000000000050'),null::uuid,'disabled rendering projects Default');
select is((select count(*) from public.get_public_map_events(-122.4,37.7,-122.1,37.9,now(),now()+interval '7 days',null) where event_id='29000000-0000-4000-8000-000000000050'),1::bigint,'disabled icon never removes event');
update private.map_icon_settings set rendering_enabled=true;
update private.map_icon_versions set state='revoked' where id='29000000-0000-4000-8000-000000000031';
select is((select map_icon_version_id from public.get_public_map_events(-122.4,37.7,-122.1,37.9,now(),now()+interval '7 days',null) where event_id='29000000-0000-4000-8000-000000000050'),null::uuid,'revoked version projects Default');
select is((select count(*) from public.get_public_map_events(-122.4,37.7,-122.1,37.9,now(),now()+interval '7 days',null) where event_id='29000000-0000-4000-8000-000000000050'),1::bigint,'revocation never removes public event');
select * from finish();
rollback;
